public class OutOfStockException extends Exception {
    public OutOfStockException(String message) { super(message); }
}

public class InvalidQuantityException extends RuntimeException {
    public InvalidQuantityException(String message) { super(message); }
}

public abstract class Item {
    private String name;
    private int stock;
    private double price;
    public Item(String name, int stock, double price) { this.name = name; this.stock = stock; this.price = price; }
    public String getName() { return name; }
    public int getStock() { return stock; }
    public double getPrice() { return price; }
    public void setStock(int stock) { if (stock < 0) throw new IllegalArgumentException("Stock cannot be negative."); this.stock = stock; }
    public void sell(int qty) throws OutOfStockException {
        if (qty <= 0) throw new InvalidQuantityException("Quantity must be positive.");
        if (qty > stock) throw new OutOfStockException(name + ": only " + stock + " left.");
        stock -= qty;
    }
    public abstract String getUnit();
}

public class Grocery extends Item {
    private String unit;
    public Grocery(String name, int stock, double price, String unit) { super(name, stock, price); this.unit = unit; }
    @Override public String getUnit() { return unit; }
}

public class Main {
    public static void main(String[] args) {
        Grocery rice = new Grocery("Rice", 5, 50.0, "kg");
        try {
            rice.sell(2);
            System.out.println(rice.getName() + " left: " + rice.getStock() + " " + rice.getUnit());
        } catch (OutOfStockException e) {
            System.out.println("Sorry: " + e.getMessage());
        } finally {
            System.out.println("Store check finished.");
        }
    }
}

